WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') search_key,%s::integer uid,%s::integer lim), s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.id_oi,a.ln,a.stt,a.staff_code,a.staff_name,a.select_yn,a.date0,a.time0,a.staff_code2,a.staff_name2,a.chinh_phu,a.ma_cdsx,a.ly_do,a.ten_ly_do,a.time_kt,a.status,a.sl_th,a.sl_ok,a.sl_ng,a.sl_kh,a.sl_bo_shot,a.sl_dong_thung,a.ma_sp,a.date_kt,a.step_code,a.mes_scheduling_code,a.branch_code,count(*) OVER() total FROM public.mes_oi_nv_dung_may a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.date0 BETWEEN s.d1 AND s.d2 AND (s.search_key='' OR a.id_oi ILIKE '%%'||s.search_key||'%%' OR a.staff_code=ANY(string_to_array(s.search_key,',')) OR a.ma_sp=ANY(string_to_array(s.search_key,','))) AND (s.all_branch OR a.branch_code=ANY(string_to_array(s.bs,','))) ORDER BY a.date0 DESC,a.time0 DESC,a.id_oi,a.ln LIMIT (SELECT lim FROM p);
